    pub fn new_benchmark_child(
        project: &ProjectRoot,
        connection: AiStudioConnection,
        benchmark_run: &std::path::Path,
    ) -> Result<Self, String> {
        let mut panel = Self::new_with_campaign_recovery(project, connection, false)?;
        panel.configure_benchmark_child(benchmark_run)?;
